contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _value, uint _fund) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(_fund > 0);
        require(address(this).balance >= _fund);
        c.sendMoney(address(c), _fund); if (__ESBMC_reverted()) return;

        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;

        bool reverted;
        c.withdraw(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;

        assert(
            reverted
                ? _value > cBalBefore && cBalAfter == cBalBefore && thisBalAfter == thisBalBefore
                : _value <= cBalBefore && cBalAfter == cBalBefore - _value && thisBalAfter == thisBalBefore + _value
        );
    }

    receive() external payable {}
}

