pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 _value, uint256 _fund) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(_fund > 0);
        vm.assume(address(this).balance >= _fund);
        try c.sendMoney(address(c), _fund) {} catch { return; }
        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;
        bool reverted;
        try c.withdraw(_value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;
        assertTrue(reverted
                ? _value > cBalBefore && cBalAfter == cBalBefore && thisBalAfter == thisBalBefore
                : _value <= cBalBefore && cBalAfter == cBalBefore - _value && thisBalAfter == thisBalBefore + _value);
    }

    function testFuzz_run(uint256 _value, uint256 _fund) public {
        _run(_value, _fund);
    }

    receive() external payable {}
}
